notes.frontend_rendering:
Pseudocode for rendering a tea's tasting notes:

const taxonomy = loadJSON('tasting-taxonomy.json')
const termMap = {}
taxonomy.categories.forEach(cat => {
  cat.groups.forEach(group => {
    group.terms.forEach(term => {
      termMap[term.id] = { label: term.label, category: cat.id, categoryName: cat.name }
    })
  })
})

function renderTastingNotes(tea) {
  const categories = ['flavor', 'body', 'finish', 'feeling', 'liquor-color', 'brewing']
  return categories
    .filter(cat => tea.tasting[cat]?.length > 0)
    .map(cat => ({
      name: termMap[tea.tasting[cat][0]].categoryName,
      terms: tea.tasting[cat].map(id => termMap[id]?.label || id)
    }))
}
